public void testUnmap_1_oe() throws Exception {
    get("/tobeunmapped", (q, a) -> "tobeunmapped");
    awaitInitialization();

    SparkTestUtil.UrlResponse response = testUtil.doMethod("GET", "/tobeunmapped", null);
    Assert.assertEquals(200, response.status);
}

focal_method:
public void awaitInitialization() {
        if (!initialized) {
    	        throw new IllegalStateException("Server has not been properly initialized");
        }

        try {
            initLatch.await();
        } catch (InterruptedException e) {
            LOG.info("Interrupted by another thread");
            Thread.currentThread().interrupt();
        }
    }

